/* Concrete preparation operations. No established plant is rendered while the
   medium is sieved, washed or fertilized. Seedlings have juvenile leaf geometry. */
(()=>{'use strict';const M=CultureModels,TAU=Math.PI*2,blue='#78b5c0';
const operations={soil:{1:['土堆与去杂','摇筛与落土','筛后混匀'],2:['溶解磷盐','均匀喷洒','盆内混匀'],3:['出苗小苗','选留壮苗','定苗完成']},sand:{1:['洗净石英砂','铺层装砂','定植小苗'],2:['共同背景','磷钾配平','混匀定容']},hydro:{1:['加入背景液','逐项混匀','定容待用'],2:['磷盐梯度','补齐钾量','分别配液'],3:['选择小苗','泡沫固定','根系入液']}};
const get=(type,step)=>operations[type]?.[step]||null;
function bench(w){w.box(0,-.25,0,12.6,.24,6.7,'#dce1cf');for(const x of [-5,5])for(const z of [-2.5,2.5])w.box(x,-1.2,z,.12,.95,.12,'#b9c5ad')}
function ring(w,x,y,z,r,c='#d4ddca',width=2){w.line(Array.from({length:49},(_,i)=>[x+Math.cos(i/48*TAU)*r,y,z+Math.sin(i/48*TAU)*r]),c,width)}
function heap(w,x,y,z,r=1.5,height=1,color='#aa875a'){const n=36,rings=[{r:0,h:height},{r:r*.3,h:height*.86},{r:r*.65,h:height*.48},{r:r,h:0}],shade=['#a08157','#a78a5d','#9a7d54','#ad9062'],p=(a,R)=>{const irregular=1+.045*Math.sin(a*5)+.025*Math.cos(a*9);return [x+Math.cos(a)*R.r*irregular,y+R.h*(R.r===0?1:1+.035*Math.sin(a*4)),z+Math.sin(a)*R.r*irregular]};for(let j=0;j<3;j++)for(let i=0;i<n;i++){const a=i/n*TAU,b=(i+1)/n*TAU,A=rings[j],B=rings[j+1],c=color==='#aa875a'?shade[(i+j)%4]:color;w.poly([p(a,A),p(a,B),p(b,B)],c);if(j>0)w.poly([p(a,A),p(b,B),p(b,A)],c)}for(let i=0;i<90;i++){const a=i*2.399,q=Math.sqrt((i+.5)/90)*.97,rr=r*q,f=q<.3?1-.14*q/.3:q<.65?.86-.38*(q-.3)/.35:.48*(1-q)/.35,yy=y+height*f;w.dot([x+Math.cos(a)*rr,yy+.025,z+Math.sin(a)*rr],.018+(i%4)*.008,color==='#aa875a'?shade[i%4]:'#e8d8ad')}}
function tray(w,x,y,z,width=3,depth=2.5){w.box(x,y,z,width,.1,depth,'#b8c6aa');for(const zz of [z-depth/2,z+depth/2])w.box(x,y+.1,zz,width,.16,.08,'#cbd5bb');for(const xx of [x-width/2,x+width/2])w.box(xx,y+.1,z,.08,.16,depth,'#cbd5bb')}
function pot(w,x,y,z,type='soil',{fill=true}={}){return CultureEquipment.pot(w,x,y,z,type,{fill,height:1.75})}
function beaker(w,x,y,z,r=.62,h=1.2,level=.7,{label='',color=blue}={}){w.cylinder(x,y,z,r,h,'#bed8cf',{n:26,alpha:.13});w.cylinder(x,y+.03,z,r*.96,h*level,color,{n:26,alpha:.42});ring(w,x,y+h,z,r);for(let i=1;i<5;i++)w.line([[x-r,y+h*i/5,z],[x-r+.12,y+h*i/5,z]],'#a8bdae',1);w.label([x,y-.15,z],label,{size:11,pill:true});}
function stir(w,x,y,z,r=.45){const a=w.time*.8;w.line([[x+Math.cos(a)*r,y,z+Math.sin(a)*r],[x+Math.cos(a)*r*.2,y-1.1,z+Math.sin(a)*r*.2]],'#c3d4cf',3);for(let i=0;i<14;i++){const aa=a+i*TAU/14;w.dot([x+Math.cos(aa)*r*.7,y-.7+(i%3)*.1,z+Math.sin(aa)*r*.7],.027,'#73aeb9')}}
function seedling(w,x,y,z,{roots=false,rootLength=.8,scale=1}={}){const point=p=>[x+p[0]*scale,y+p[1]*scale,z+p[2]*scale],sway=Math.sin(w.time*1.1)*.015;w.cylinder(x,y,z,.025*scale,.55*scale,'#6f974b',{n:8});for(let i=0;i<3;i++){const side=i%2?1:-1,base=.11+i*.15,len=[.58,.82,.7][i],pts=[];for(let j=0;j<=16;j++){const t=j/16,yy=base+.35*Math.sin(Math.PI*t*.8)-.15*t*t;pts.push([side*len*t+sway*t,yy,(i-1)*.09*t])}for(let j=0;j<16;j++){const t=j/16,u=(j+1)/16,a=pts[j],b=pts[j+1],wa=Math.sin(Math.PI*t)*.052,wb=Math.sin(Math.PI*u)*.052;w.poly([point([a[0],a[1]+wa*.65,a[2]-wa*.76]),point([b[0],b[1]+wb*.65,b[2]-wb*.76]),point([b[0],b[1]-wb*.65,b[2]+wb*.76]),point([a[0],a[1]-wa*.65,a[2]+wa*.76])],i%2?'#6b9447':'#79a14f')}w.line(pts.map(point),'#b9ce86',.6);w.cylinder(x,y+base*scale,z,.032*scale,.09*scale,'#85a45b',{n:8})}w.line([[x,y+.45*scale,z],[x+.04*scale,y+.78*scale,z],[x+.08*scale,y+.89*scale,z]],'#6c9847',2);if(roots)for(let i=0;i<5;i++){const a=i/5*TAU,r=.13+i*.04,end=[x+Math.cos(a)*r,y-rootLength*(.7+i*.06),z+Math.sin(a)*r];w.line([[x,y,z],[x+Math.cos(a)*.08,y-.2,z+Math.sin(a)*.08],end],'#eadbb4',1.1);for(let j=1;j<=3;j++){const f=j/4,p=[x+(end[0]-x)*f,y+(end[1]-y)*f,z+(end[2]-z)*f];w.line([p,[p[0]+Math.cos(a+.8)*.12,p[1]-.12,p[2]+Math.sin(a+.8)*.12]],'#e6d8b4',.6)}}}
function soilSieve(w,s){bench(w);const op=s.operation||0;heap(w,-3.9,.02,0,1.6,1.15);for(let i=0;i<6;i++)w.dot([-4.5+i*.2,.65+(i%2)*.1,-.2+(i%3)*.17],.13+(i%3)*.025,'#866748');w.label([-3.9,1.8,0],'同一批风干土 · 去石块、根茬',{size:12,pill:true});tray(w,.1,.02,0,3.2,2.7);if(op>0)heap(w,.1,.15,0,1,.38);
const shake=op===1?Math.sin(w.time*7)*.12:0,cx=.1+shake,yy=1.9;for(const z of [-1.2,1.2])w.box(cx,yy,z,3,.16,.12,'#b9a57a');for(const x of [cx-1.5,cx+1.5])w.box(x,yy,0,.12,.16,2.5,'#b9a57a');for(let i=0;i<=12;i++){const q=-1.38+i*.23;w.line([[cx+q,yy,-1.1],[cx+q,yy,1.1]],'#8f9c8a',.75)}for(let i=0;i<=10;i++){const z=-1.1+i*.22;w.line([[cx-1.4,yy,z],[cx+1.4,yy,z]],'#8f9c8a',.75)}if(op===1){for(let i=0;i<23;i++)w.dot([cx-.85+(i*.319)%1.7,yy+.14+(i%3)*.06,-.7+(i*.237)%1.4],.06+(i%3)*.015,'#ad8c5c');for(let i=0;i<35;i++){const f=(w.time*.5+i/35)%1;w.dot([cx-.95+(i*.37)%1.9,yy-f*1.55,-.8+(i*.31)%1.6],.025+(i%3)*.007,'#a48960')}w.stream([[-3.1,1.5,0],[-1,2.5,0],[0,2.1,0]],'#a58a60',{count:7,size:.04,speed:.15,trail:false})}w.label([cx,2.55,0],op===1?'摇动 3 mm 筛 · 细土落下':'3 mm 土壤筛',{size:13,pill:true});if(op===2){heap(w,3.65,.02,0,1.45,.8);w.label([3.65,1.45,0],'筛后土全量混匀',{size:13,pill:true});w.arrow([1.6,.5,0],[2.3,.5,0],'#8b9a7b')}w.label([0,-.4,2.2],'大土块捣碎后再筛，不把土块直接丢弃',{size:11,pill:true})}
function soilFertilize(w,s){bench(w);const op=s.operation||0,top=pot(w,2.3,.02,0),d=M.dose('soil',s.treatment,5);beaker(w,-3.5,.03,0,.7,1.5,.7,{label:s.treatment?'KH₂PO₄ + 水':'P₀：不加磷盐，补等量水'});if(op===0){if(s.treatment)for(let i=0;i<18;i++){const f=(w.time*.4+i/18)%1;w.dot([-3.5+.23*Math.sin(i*2),2.1-f*1.8,.2*Math.cos(i)],.028,'#e7e9da')}stir(w,-3.5,1.7,0);w.label([-3.5,2.65,0],`称取 KH₂PO₄ ${d.kh2po4Mg.toFixed(1)} mg`,{size:12,pill:true});w.label([2.3,2.45,0],'盆内供试土 · 尚未播种',{size:13,pill:true})}
if(op===1){w.cylinder(-.6,.03,0,.45,1.45,'#a9c8bf',{n:22,alpha:.55});w.cylinder(-.6,.1,0,.4,1.1,blue,{n:22,alpha:.45});w.cylinder(-.6,1.48,0,.14,.34,'#a0b29a',{n:12});w.line([[-.7,1.95,0],[-.2,1.95,0],[.1,2.25,0],[.55,2.25,0]],'#9eaf98',6);w.line([[-.45,1.94,0],[-.12,1.65,0]],'#8ba17e',3);const swing=Math.sin(w.time*.7)*.5;for(let i=0;i<14;i++){const a=i*2.399,rr=.9*Math.sqrt((i+.5)/14),end=[2.3+Math.cos(a)*rr,top+.03,Math.sin(a)*rr];w.stream([[.55,2.25+swing*.1,0],[1.2,2.35,end[2]*.4],end],blue,{count:3,size:.021,speed:.22,phase:i*.07,trail:false})}w.arrow([-2.4,1,0],[-1.2,1,0],blue);w.label([2.3,2.9,0],'细雾扫过整个土面',{size:14,pill:true});w.label([-.6,-.2,0],'装入喷壶',{size:11,pill:true})}
if(op===2){const a=w.time*.9,x=2.3+Math.cos(a)*.45,z=Math.sin(a)*.45;w.line([[x,top+1,z],[x,top-.7,z]],'#b0b8aa',5);w.poly([[x-.15,top-.3,z-.1],[x+.15,top-.3,z-.1],[x+.18,top-.8,z+.05],[x-.18,top-.8,z+.05]],'#a5afa0');for(let i=0;i<16;i++){const aa=a+i/16*TAU;w.dot([2.3+Math.cos(aa)*.7,top-.2+Math.sin(aa*2)*.25,Math.sin(aa)*.7],.035,'#76adb4')}w.label([2.3,3.15,0],'分次喷洒后，盆内全层混匀',{size:14,pill:true});}w.label([0,-.45,2.2],'施磷在播种前完成 · K 配平另核对 · 各盆加液总量相同',{size:11,pill:true})}
function soilSeedlings(w,s){bench(w);const op=s.operation||0,top=pot(w,1,.02,0);seedling(w,1,top+.03,0,{roots:op===2,scale:1.15});if(op<2)for(const side of [-1,1])seedling(w,1+side*.65,top+.03,.25,{scale:.65});w.label([1,3.15,0],['盆中出苗 · 苗龄一致','选留中央壮苗','定苗后，每盆 1 株玉米小苗'][op],{size:15,pill:true});tray(w,-3.3,.02,0,2.5,2);if(op===1){w.line([[-.5,2.5,0],[-.15,2.25,0],[-.45,1.95,0]],'#a1ada0',3);w.line([[-.5,1.95,0],[-.15,2.25,0],[-.45,2.5,0]],'#a1ada0',3);w.label([-3.3,1.1,0],'剪除多余弱苗，避免扰动留苗根系',{size:12,pill:true})}else w.label([-3.3,1.1,0],op===0?'催芽播种后，等待整齐出苗':'定苗完成后开始统一管理与记录',{size:12,pill:true});w.label([1,-.4,1.4],'三叶期幼苗 · 展开叶与心叶',{size:10,pill:true})}
function sandPreparation(w,s){bench(w);const op=s.operation||0;beaker(w,-3.4,.03,0,1,1.15,.65,{label:op===0?'清洗石英砂':'洗净后检验洗液与背景磷',color:op===0?'#b3bdad':blue});heap(w,-3.4,.12,0,.8,.35,'#d8c99f');if(op===0){w.stream([[-4.6,2.4,0],[-3.8,1.6,0],[-3.4,.5,0]],blue,{count:10,size:.035,speed:.2});w.label([-3.4,2.8,0],'清洗 → 沉降 → 换水',{size:13,pill:true})}const top=pot(w,2.2,.02,0,'sand',{fill:op>=1});if(op>=1){w.cylinder(2.2,.12,0,1.08,.32,'#bbab83',{n:24});w.label([2.2,.5,-1.1],'底层粗砂 + 挡砂层',{size:10,pill:true});if(op===1){for(let i=0;i<25;i++){const f=(w.time*.35+i/25)%1;w.dot([2.2+.6*Math.sin(i*2),3-f*1.2,.6*Math.cos(i*2)],.035,'#ddcba0')}w.label([2.2,3.45,0],'装入洗净细砂 · 留出盆沿',{size:13,pill:true})}else{seedling(w,2.2,top+.03,0,{roots:true,scale:1.15});w.label([2.2,3.2,0],'相同装砂量 · 每盆 1 株小苗',{size:13,pill:true})}}else w.label([2.2,2.5,0],'清洁空盆 · 排液孔保持畅通',{size:12,pill:true});w.label([0,-.45,2],'清洗与平衡完成后，才装盆、定植和接入供液回路',{size:11,pill:true})}
function nutrientPreparation(w,s){bench(w);const op=s.operation||0,d=M.dose(s.type,s.treatment,5),target=2.1;beaker(w,target,.03,0,1.1,2,.55+op*.15,{label:op===2?'本处理工作液 · 定容至 5 L':'先加大部分水，再逐项配液'});const labels=['共同背景液','KH₂PO₄','KCl 补钾'];for(let i=0;i<3;i++){const x=-4.7+i*1.4;beaker(w,x,.03,-.1,.4,1.05,.6,{label:labels[i]})}const from=op===0?-4.7:op===1?-3.3:-1.9;w.stream([[from,1.2,-.1],[from+.5,2.7,0],[target,2.15,0]],blue,{count:8,size:.033,speed:.16});stir(w,target,2.6,0,.65);w.label([2.1,3.65,0],op===0?'各贮备液分别加入水中':op===1?`P ${d.pMmol.toFixed(2)} + KCl ${d.kclMmol.toFixed(2)} mmol/L`:'充分混匀 → 定容 → 核对 pH',{size:14,pill:true});w.label([0,-.45,2],'浓钙液与浓磷液分开稀释，加入后充分混匀',{size:11,pill:true})}
function hydroSeedlings(w,s){bench(w);const op=s.operation||0;tray(w,-3.5,.03,0,3,2.3);for(let i=0;i<4;i++)seedling(w,-4.35+i*.55,.18,0,{roots:false,scale:.65});w.label([-3.5,1.55,0],'选择同龄、大小一致的玉米小苗',{size:12,pill:true});beaker(w,2,.03,0,1.2,1.75,.86,{label:'本处理营养液 · 根颈高于液面'});for(let i=0;i<32;i++){const a=i/32*TAU,b=(i+1)/32*TAU,p=(t,r)=>[2+Math.cos(t)*r,1.82,Math.sin(t)*r];w.poly([p(a,.23),p(a,1.24),p(b,1.24),p(b,.23)],'#92aa87')}const crown=op===1?2.8:1.9;if(op>0){w.cylinder(2,crown-.06,0,.18,.1,'#d5dfc8',{n:18});seedling(w,2,crown,0,{roots:true,rootLength:1.25,scale:1.15});w.label([2,4.1,0],op===1?'泡沫轻夹固定 · 不夹伤根颈':'根系浸液，根颈和叶片留在液面以上',{size:13,pill:true});if(op===1)w.arrow([2,2.4,-.65],[2,1.9,-.65],'#7e9b75')}else w.label([2,2.4,0],'配液完成，等待定植',{size:13,pill:true});}
const previous=CultureWorlds.draw;CultureWorlds.draw=(w,s)=>{const ops=get(s.type,s.step);w.canvas.dataset.operationScene=ops?`${s.type}-${s.step}-${s.operation||0}`:'main';if(!ops)return previous(w,s);if(s.type==='soil'){if(s.step===1)soilSieve(w,s);else if(s.step===2)soilFertilize(w,s);else soilSeedlings(w,s)}else if(s.type==='sand'&&s.step===1)sandPreparation(w,s);else if(s.type==='hydro'&&s.step===3)hydroSeedlings(w,s);else nutrientPreparation(w,s)};
window.CulturePractical={get,seedling};
})();


